const { NodeSDK } = require('@opentelemetry/sdk-node');
const { getNodeAutoInstrumentations } = require('@opentelemetry/auto-instrumentations-node');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-trace-otlp-http');
const { Resource } = require('@opentelemetry/resources');
const { SemanticResourceAttributes } = require('@opentelemetry/semantic-conventions');
const { CompressionAlgorithm } = require('@opentelemetry/exporter-otlp-http');
const logger = require('./utils/pino-logger');
const { PinoInstrumentation } = require('@opentelemetry/instrumentation-pino');

// Initialize the SDK and register with the OpenTelemetry API
// This enables the API to record telemetry
const startOpenTelemetry = (name, env) => {
  const exporterOptions = {
    url: `${process.env.OPEN_TELEMETRY_HOST}/v1/traces`,
    keepAlive: true,
    compression: CompressionAlgorithm.GZIP,
    headers: {
      authorization: `${process.env.OPEN_TELEMETRY_API_KEY}`,
    },
  };

  const traceExporter = new OTLPTraceExporter(exporterOptions);

  const sdk = new NodeSDK({
    traceExporter,
    instrumentations: [getNodeAutoInstrumentations(), new PinoInstrumentation({
        logHook: (span, record) => {
          // Attach logs to spans or enrich logs
          record['traceId'] = span.spanContext().traceId;
        },
      })],
    resource: new Resource({
      [SemanticResourceAttributes.SERVICE_NAME]: `Node-red-${name}-${env}`,
    }),
  });

  // Gracefully shut down the SDK on process exit
  process.on('SIGTERM', () => {
    sdk
      .shutdown()
      .then(() => logger.info('Tracing terminated'))
      .catch((error) => logger.error(error, 'Error terminating tracing'))
      .finally(() => process.exit(0));
  });

  sdk.start();
  logger.debug('otel sdk init done');
};

if (`${process.env.OPEN_TELEMETRY_STATE}` === 'enabled') {
    startOpenTelemetry(`${process.env.APP_NAME}`, `${process.env.NODE_ENV}`);
}